use std :: path :: Path ; use crate :: { Match , MatchResult } ; # [doc = " Truncates a key string for display purposes"] # [doc = ""] # [doc = " If the key length is 20 characters or less, returns it unchanged."] # [doc = " Otherwise, shows the first 13 characters and last 4 characters with \"...\" in"] # [doc = " between."] # [doc = ""] # [doc = " # Arguments"] # [doc = " * `key` - The key string to truncate"] # [doc = ""] # [doc = " # Returns"] # [doc = " * A truncated version of the key for safe display"] pub use forge_domain :: truncate_key ; use sha2 :: { Digest , Sha256 } ; use pretty_assertions :: assert_eq ; use serde_json :: json ; use super :: * ; # [doc = " Computes SHA-256 hash of the given content"] # [doc = ""] # [doc = " General-purpose utility function that computes a SHA-256 hash of string"] # [doc = " content. Returns a consistent hexadecimal representation that can be used"] # [doc = " for content comparison, caching, or change detection."] # [doc = ""] # [doc = " # Arguments"] # [doc = " * `content` - The content string to hash"] # [doc = ""] # [doc = " # Returns"] # [doc = " * A hexadecimal string representation of the SHA-256 hash"] pub fn compute_hash (content : & str) -> String { use sha2 :: { Digest , Sha256 } ; let mut hasher = Sha256 :: new () ; hasher . update (content . as_bytes ()) ; hex :: encode (hasher . finalize ()) }